const fs=require("fs"),cp=require("child_process"),crypto=require("crypto");
const hash=b=>crypto.createHash("sha256").update(b).digest("hex");
const git=args=>cp.execFileSync("git",args);
const paths=["scripts/team-service-baseline.mjs","scripts/team-service-baseline.test.mjs","scripts/team-service-plan-contract.test.mjs","docs/팀서비스-자동흐름-구현계획.md","docs/team/service-flow-acceptance.json","docs/team/service-flow-state-contract.json"];
const target_commit=git(["rev-parse","HEAD"]).toString().trim();
const capture=()=>paths.map(path=>{const b=fs.readFileSync(path);if(!b.equals(git(["show",target_commit+":"+path])))throw Error("uncommitted source");return {path,sha256:hash(b)};});
const sources=capture();
const args=["--test","--test-reporter=tap","scripts/team-service-baseline.test.mjs","scripts/team-service-plan-contract.test.mjs"];
const run=cp.spawnSync(process.execPath,args,{encoding:"utf8",shell:false,windowsHide:true,timeout:30000});
if(JSON.stringify(sources)!==JSON.stringify(capture())||target_commit!==git(["rev-parse","HEAD"]).toString().trim())throw Error("source changed");
console.log(JSON.stringify({kind:"LOCAL_SPEC_EVIDENCE_NOT_SERVICE_PASS",target_commit,sources,command:{executable:process.execPath,args},exit_code:run.status,stdout:run.stdout,stderr:run.stderr,stdout_sha256:hash(run.stdout),service_ready:false,ac_executed:false}));
